@pytest.mark.parametrize("model_cls, payload, expected_dump", MODEL_CASES)
def test_generated_model_roundtrip(
    model_cls: type[StoneXModel],
    payload: dict[str, object],
    expected_dump: dict[str, object],
) -> None:
    first = model_cls.model_validate(payload).model_dump(by_alias=True, exclude_unset=True)
    for key, expected in expected_dump.items():
        assert key in first
        assert first[key] == expected
    round_tripped = model_cls.model_validate(first)
    assert round_tripped.model_dump(by_alias=True, exclude_unset=True) == first


