def test_request_variant_rejects_unknown_key(
    model_cls: type[StoneXModel], payload: dict[str, object]
) -> None:
    with pytest.raises(ValidationError) as caught:
        model_cls.model_validate(payload | {"__unknown__": 1})
    assert any(
        error["type"] == "extra_forbidden" and error["loc"] == ("__unknown__",)
        for error in caught.value.errors()
    )
